#ifndef PRACTICA_ENVIO_CAJAS_H
#define PRACTICA_ENVIO_CAJAS_H

// Domain: 0 <= piezas <= 20.
// Minimum number of four-slot boxes needed for all the pieces.
// Zero pieces require zero boxes.
int cajas_para(int piezas);

#endif

#include "envio/cajas.h"

int cajas_para(int piezas) {
    const int piezas_por_caja{4};
    return (piezas + piezas_por_caja - 1) / piezas_por_caja;
}

#include "envio/cajas.h"
#include <iostream>

int main() {
    std::cout << cajas_para(4) << ":" << cajas_para(8);
    return 0;
}

#include "envio/cajas.h"
#include <iostream>

bool comprobar(int piezas, int esperado) {
    const int obtenido{cajas_para(piezas)};
    const bool coincide{obtenido == esperado};
    std::cout << "piezas=" << piezas << " expected=" << esperado
              << " actual=" << obtenido << " ";
    if (coincide) { std::cout << "OK\n"; }
    else { std::cout << "FAIL\n"; }
    return coincide;
}

int main() {
    bool correcto{true};
    if (!comprobar(0, 0)) { correcto = false; }
    if (!comprobar(4, 1)) { correcto = false; }
    if (!comprobar(8, 2)) { correcto = false; }
    if (!comprobar(20, 5)) { correcto = false; }
    if (!comprobar(1, 1)) { correcto = false; }
    if (!comprobar(5, 2)) { correcto = false; }
    if (!comprobar(17, 5)) { correcto = false; }
    if (!correcto) {
        std::cout << "Suite: FAIL\n";
        return 1;
    }
    std::cout << "Suite: OK\n";
    return 0;
}

